```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, count(*) n, min(value) mn, max(value) mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'rate-%' GROUP BY metric ORDER BY metric", "claim": "Rate pod in the abnormal window reports only restarts (2 to 6), ready=0 and phase, with no other metrics."},
        {"kind": "trace", "sql": "SELECT 'abn' p, count(*) n FROM abnormal_traces WHERE service_name='rate' UNION ALL SELECT 'norm', count(*) FROM normal_traces WHERE service_name='rate'", "claim": "Rate emits no spans at all in the abnormal period, versus about 1390 spans in the normal period."},
        {"kind": "trace", "sql": "SELECT attr_status_code, count(*) n, round(avg(duration/1e6),3) avg_ms FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' AND service_name='search' GROUP BY 1", "claim": "Every search-to-rate GetRates call fails (490 of 490) in about 0.01 ms, i.e. immediate refusal."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE message LIKE '%rate service%' GROUP BY ALL", "claim": "Search logs 'Failed to get rates from rate service' repeatedly during the incident."}
      ]
    }
  ],
  "propagation": [
    {"from": "rate", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('rate.Rate/GetRates','search.Search/Nearby') GROUP BY ALL ORDER BY 1,2,3", "claim": "Search's rate.Rate/GetRates client spans all error, and every search.Search/Nearby server span errors with them."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code, attr_status_code, count(*) n FROM abnormal_traces WHERE (service_name='frontend' AND span_name IN ('search.Search/Nearby','HTTP /hotels')) GROUP BY ALL ORDER BY 1,2", "claim": "All 744 frontend search calls error and all 744 frontend HTTP /hotels requests return 500."}]}
  ]
}
```

